const readOptional=async file=>{try{return await readQueueObject(file);}catch(error){if(error.code==='ENOENT')return null;throw error;}};
function commonFields(intent){return {intentSha256:intent.sha256,binding:intent.value.binding};}
async function sameOrCreate(file,value){try{return await durableCreate(file,value);}catch(error){if(error.code!=='EEXIST')throw error;const old=await readQueueObject(file);assert.deepEqual(old.value,value,'Immutable retirement record differs');return old.sha256;}}
async function readIntent(config,dispatchId,intentSha256,{allowMissingBan=false}={}){
 assert.match(dispatchId??'',uuid);assert.match(intentSha256??'',hex);const directory=retirementDirectory(config,dispatchId),record=await readQueueObject(path.join(directory,'INTENT.json'));assert.equal(record.sha256,intentSha256,'Use the exact frozen retirement intent');assert.equal(record.value.version,retirementIntentVersion);assert.equal(record.value.binding.dispatchId,dispatchId);assert.equal(record.value.configFile,path.resolve(record.value.configFile));assert.equal(record.value.configSha256,sha(await stableBytes(record.value.configFile)));const ban=allowMissingBan?await readOptional(path.join(directory,'TARGET-BAN.json')):await readQueueObject(path.join(directory,'TARGET-BAN.json'));if(ban){assert.equal(ban.value.version,retirementBanVersion);assert.equal(ban.value.intentSha256,intentSha256);assert.equal(ban.value.selectedTarget,record.value.binding.selectedTarget);assert.equal(ban.value.forbidTargetReplay,true);}const initial=await readRetirementEvidence(retirementEvidenceDirectory(directory),record.value.initialClosure);assert.deepEqual(initial.binding,record.value.binding);assert.equal(initial.runDirectory,directory);assert.equal(initial.archiveRoot,path.join(config.stateDirectory,'ra',dispatchId.replaceAll('-','')));for(const action of [...initial.sourceActions,...initial.artifactActions]){assert.equal(action.objectId,sha(Buffer.from(key(action.source))));assert.equal(action.destination,path.join(initial.archiveRoot,'o',action.objectId.slice(0,16)));assert.ok(!isRetirementChild(initial.archiveRoot,action.source));}return {...record,directory,initial};
}
async function originalCas(config,intent){const directory=path.join(config.stateDirectory,'prebuild-queue-v2'),d=await readQueueObject(path.join(directory,'dispatches',intent.value.binding.dispatchId+'.json')),t=await readQueueObject(path.join(directory,'results',intent.value.binding.requestId+'.json'));assert.deepEqual(retirementBinding(d.value,t.value),intent.value.binding);return {dispatch:d.value,terminal:t.value};}
async function adoptedCas(context,intent){await assertControlGeneration(context.adopted);assert.equal(context.adopted.stateSha256,intent.value.adoption.stateSha256,'Retirement execution requires its original adopted control generation');await originalCas(context.config,intent);assert.deepEqual((await loadRetirementNativeTools(context.config)).files,context.native.files);await assertRetirementGitFence(context);}
async function captureRetirementControl(context){const state=context.adopted.state,files={installation:path.join(context.config.stateDirectory,'CONTROL-INSTALLATION.json'),manifest:path.join(context.bundleRoot,'MANIFEST.json'),upgradeIntent:path.join(context.config.stateDirectory,'control-upgrades',state.installId,'INTENT.json'),transition:state.transitionProofFile,dispatcher:path.join(context.config.stateDirectory,'control/tools/publish-latest-main.mjs'),hook:state.hook},result={};for(const [name,file] of Object.entries(files)){const raw=await stableBytes(file);result[name]={raw:raw.toString('utf8'),sha256:sha(raw)};}assert.equal(result.installation.sha256,context.adopted.stateSha256);assert.equal(result.manifest.sha256,state.bundleManifestSha256);assert.equal(result.upgradeIntent.sha256,state.intentSha256);assert.equal(result.transition.sha256,state.transitionProofSha256);assert.equal(result.dispatcher.sha256,state.dispatcherSha256);assert.equal(result.hook.sha256,state.hookSha256);return result;}
async function validateFrozenRetirementControl(intent,control){
 const state={...intent.value.adoption};delete state.stateSha256;for(const [name,record] of Object.entries(control)){assert.ok(['installation','manifest','upgradeIntent','transition','dispatcher','hook'].includes(name));assert.equal(sha(Buffer.from(record.raw)),record.sha256);}assert.deepEqual(Object.keys(control).sort(),['installation','manifest','upgradeIntent','transition','dispatcher','hook'].sort());assert.equal(control.installation.sha256,intent.value.adoption.stateSha256);assert.deepEqual(JSON.parse(control.installation.raw),state);assert.equal(state.version,'teruisi-main-control-installation-v3');assert.equal(state.status,'adopted');const manifest=JSON.parse(control.manifest.raw);assert.equal(control.manifest.sha256,state.bundleManifestSha256);assert.equal(control.manifest.raw,canonical(manifest));assert.equal(manifest.version,'teruisi-main-control-bundle-v2');assert.equal(manifest.preparationRetirementProtocol,retirementIntentVersion);assert.equal(manifest.preparationRetirementRefProtocol,'teruisi-retired-manual-main-ref-fence-v1');assert.equal(manifest.bundleSha256,state.bundleSha256);assert.equal(sha(Buffer.from(canonical(manifest.files))),state.bundleSha256);assert.equal(path.resolve(state.bundleRoot),path.join(path.dirname(intent.directory),'..','control-bundles',state.bundleSha256));assert.match(manifest.sourceCommit,/^[a-f0-9]{40}$/);assert.match(manifest.sourceTree,/^[a-f0-9]{40}$/);const actualNames=(await fs.readdir(path.join(state.bundleRoot,'tools'))).sort();assert.deepEqual(actualNames,Object.keys(manifest.files).map(x=>x.slice('tools/'.length)).sort());for(const [name,digest] of Object.entries(manifest.files)){assert.ok(/^tools\/[a-z0-9-]+\.mjs$/.test(name)||name==='tools/preparation-retirement-handoff-runner.ps1');assert.equal(sha(await stableBytes(path.join(state.bundleRoot,...name.split('/')))),digest,'Original frozen retirement operator changed');}
 const upgrade=JSON.parse(control.upgradeIntent.raw),transition=JSON.parse(control.transition.raw);assert.equal(control.upgradeIntent.sha256,state.intentSha256);assert.equal(upgrade.version,'teruisi-main-control-upgrade-v2');assert.equal(upgrade.installId,state.installId);assert.equal(upgrade.sourceCommit,manifest.sourceCommit);assert.equal(upgrade.sourceTree,manifest.sourceTree);for(const field of ['bundleRoot','bundleSha256','bundleManifestSha256','configSha256','dispatcherSha256','hook','hookSha256'])assert.equal(upgrade[field],state[field]);assert.deepEqual(upgrade.preparationTask,state.preparationTask);assert.equal(control.transition.sha256,state.transitionProofSha256);assert.equal(transition.version,'teruisi-main-control-transition-v2');assert.equal(transition.installId,state.installId);assert.equal(transition.intentSha256,state.intentSha256);assert.deepEqual(transition.lockOrder,['v1-queue','v2-queue','native-rotation']);assert.equal(transition.privateTestTopology,false);assert.equal(transition.productionDeploymentPerformed,false);assert.equal(transition.legacyWindowConverged,true);assert.ok(transition.frames.length>=3);for(const frame of transition.frames.slice(-3))assert.deepEqual(frame.related,[]);assert.equal(control.dispatcher.sha256,state.dispatcherSha256);assert.equal(control.hook.sha256,state.hookSha256);return manifest;
}
function actionIdentity(action){return {source:action.source,destination:action.destination,objectId:action.objectId,kind:action.kind,role:action.role,type:action.expected.type,dev:action.expected.dev,ino:action.expected.ino,registration:action.registration??null,protection:action.protection??null,dependency:action.dependency??null,manifestSha256:action.manifestSha256??null};}
function assertFrozenActions(actual,frozen){const known=new Map(frozen.map(x=>[key(x.source),x]));for(const action of actual){const old=known.get(key(action.source));assert.ok(old,'New source/object address requires a new reviewed intent');assert.deepEqual(actionIdentity(action),actionIdentity(old),'Frozen source/object identity changed');}}
async function movedActions(actions){const moved=[];for(const action of actions){const source=await retirementEntity(action.source),destination=await retirementEntity(action.destination);assert.equal(Boolean(source&&destination),false,'Both original and archive addresses exist');assert.ok(source||destination,'Original and archive addresses are both absent');if(destination){for(const field of ['type','dev','ino'])assert.equal(destination[field],action.expected[field],'Archive address is not the intended original object');moved.push(action);}}return moved;}
function assertOriginalSourcePreimage(intent,action,snapshot){if(action.kind!=='git-worktree')return;assert.equal(action.registration.HEAD,intent.value.binding.selectedTarget);assert.equal(snapshot.kind,'tree');const actual=new Map(snapshot.inventory.files.map(x=>[x.path,x.sha256]));for(const [file,digest] of Object.entries(intent.initial.sourceInventory))assert.equal(actual.get(file),digest,'Original source/producer changed before its first move: '+file);}
/** Complete all byte/link preimages before the first move, then measure one CAS.
 * A resumed call hashes again; saved hashes are never a cross-call read cache. */
async function retirementCasCombination({closureCheck,objects,before=[],after=[],clock=()=>performance.now(),signal}){
 const started=clock(),startedAt=at(),stages=[],deadlineMs=performance.now()+40000;
 const stage=async(name,run)=>{assert.ok(!signal?.aborted,'Retirement CAS cancelled');const begin=clock(),atStart=at();try{const value=await run();assert.ok(!signal?.aborted,'Retirement CAS cancelled');return value;}finally{stages.push({name,startedAt:atStart,completedAt:at(),elapsedMs:clock()-begin});}};
 const measurement=()=>({startedAt,completedAt:at(),elapsedMs:clock()-started,objects:objects.length,files:objects.reduce((n,x)=>n+(x.snapshot.kind==='file'?1:x.snapshot.inventory.files.length),0),stages});try{for(const item of before)await stage(item.name,item.run);if(closureCheck)await stage('closure-cas',closureCheck);await stage('snapshot-cas',()=>assertRetirementSnapshotsUnchanged(objects,{deadlineMs,signal}));for(const item of after)await stage(item.name,item.run);const value=measurement();assert.ok(value.elapsedMs<40000,'Complete final CAS exceeds its qualified 40 second budget; no first move or seal is allowed');return value;}catch(cause){const error=cause&&typeof cause==='object'?cause:Error('Retirement CAS check rejected',{cause});error.retirementCasMeasurement=measurement();throw error;}
}
async function preflightMoves(context,intent,actions,adapter,closure){
 const directory=path.join(intent.directory,'actions'),objects=retirementEvidenceDirectory(intent.directory),prepared=new Map();await fs.mkdir(directory,{recursive:true});
 for(const action of actions){await adapter.cas(intent);const source=await retirementEntity(action.source),destination=await retirementEntity(action.destination);assert.ok(Boolean(source)!==Boolean(destination),'Move preflight needs exactly one original object address');const root=source?action.source:action.destination,file=path.join(directory,action.objectId+'.preimage.json');let saved=await readOptional(file);const prior=saved?await readRetirementEvidence(objects,saved.value.snapshot):null,snapshot=await adapter.snapshot(action,root,prior?{qualifiedLinks:prior.qualifiedLinks}:{});assertOriginalSourcePreimage(intent,action,snapshot);if(source&&action.kind==='git-worktree')await requalifyRetirementGitSource(context,action,intent.initial.sourceInventory,intent.initial.original.sourceRoot);if(saved){assert.equal(saved.value.intentSha256,intent.sha256);assert.deepEqual(saved.value.action,actionIdentity(action));assertRetirementBytePreservation(await readRetirementEvidence(objects,saved.value.snapshot),snapshot);}else{assert.ok(source,'An already moved source without its complete preimage is unknown');const reference=await putRetirementEvidence(objects,snapshot);await durableCreate(file,{version:retirementOperatorVersion,...commonFields(intent),action:actionIdentity(action),snapshot:reference,at:at()});saved=await readQueueObject(file);}prepared.set(action.objectId,{root,snapshot,record:saved});}
 prepared.measurement=await retirementCasCombination({closureCheck:closure?()=>assertRetirementClosureUnchanged(context,closure):null,objects:[...prepared.values()],after:[...(adapter.fresh?[{name:'ordinary-task-boot-ref-native',run:()=>adapter.fresh()}]:[]),{name:'adoption-original-tail',run:()=>adapter.cas(intent)}]});return prepared;
}
async function snapshotMove(context,intent,action,adapter,preflight){
 const directory=path.join(intent.directory,'actions'),objects=retirementEvidenceDirectory(intent.directory),snapshotFile=path.join(directory,action.objectId+'.preimage.json');await fs.mkdir(directory,{recursive:true});let saved=await readOptional(snapshotFile);if(!saved){assert.ok(await retirementEntity(action.source),'A move without its complete preimage is unknown');const snapshot=await adapter.snapshot(action,action.source),reference=await putRetirementEvidence(objects,snapshot);const record={version:retirementOperatorVersion,...commonFields(intent),action:actionIdentity(action),snapshot:reference,at:at()};await durableCreate(snapshotFile,record);saved=await readQueueObject(snapshotFile);}assert.equal(saved.value.intentSha256,intent.sha256);assert.deepEqual(saved.value.action,actionIdentity(action));const before=await readRetirementEvidence(objects,saved.value.snapshot);if(await retirementEntity(action.source)){assert.ok(preflight&&preflight.root===action.source,'Same-call complete source preflight required');await assertRetirementSnapshotUnchanged(action.source,preflight.snapshot);}
 const result=await adapter.move({...action,repository:context.config.repository,actionDirectory:directory,intentSha256:intent.sha256,git:context.git}),after=await adapter.snapshot(action,action.destination,{qualifiedLinks:before.qualifiedLinks});assertRetirementBytePreservation(before,after);const preservedFile=path.join(directory,action.objectId+'.preserved.json'),preserved=await readOptional(preservedFile);if(preserved){assert.equal(preserved.value.intentSha256,intent.sha256);assert.deepEqual(preserved.value.record.action,action);assert.deepEqual(preserved.value.record.preimage,saved.value.snapshot);assert.deepEqual(preserved.value.record.result,result);assertRetirementBytePreservation(await readRetirementEvidence(objects,preserved.value.record.postimage),after);return preserved.value.record;}const record={action,preimage:saved.value.snapshot,postimage:await putRetirementEvidence(objects,after),result};await durableCreate(preservedFile,{version:retirementOperatorVersion,intentSha256:intent.sha256,record});return record;
}
function nativeAdapter(context){return {lock:()=>acquireRetirementLocks(context),cas:intent=>adoptedCas(context,intent),fresh:()=>freshRetirementContext(context),collect:options=>collectRetirementClosure(context,options),archive:root=>prepareRetirementArchive(root,context.token.sid),snapshot:(action,root,options={})=>snapshotRetirementObject(action,root,{native:context.native,...options}),move:relocateRetirementObject,detach:options=>detachRetirementHardlink({...options,sid:context.token.sid}),witness:async options=>(await import('./preparation-retirement-witness.mjs')).runRetirementWitnessRounds({...options,context})};}
async function readClosed(intent){const record=await readQueueObject(path.join(intent.directory,'SOURCES-CLOSED.json'));assert.equal(record.value.version,retirementSourcesClosedVersion);assert.equal(record.value.intentSha256,intent.sha256);assert.deepEqual(record.value.binding,intent.value.binding);const evidence=await readRetirementEvidence(retirementEvidenceDirectory(intent.directory),record.value.sourceResults);assert.equal(evidence.length,intent.initial.sourceActions.length);assert.deepEqual(evidence.map(x=>actionIdentity(x.action)),intent.initial.sourceActions.map(actionIdentity));validateFullBootObservation(record.value.preCloseBoot);const meter=record.value.preflight;assert.ok(meter&&Number.isFinite(meter.elapsedMs)&&meter.elapsedMs>=0&&meter.elapsedMs<40000,'Source preflight timing proof missing or outside its qualified budget');assert.equal(meter.objects,intent.initial.sourceActions.length);assert.ok(Number.isSafeInteger(meter.files)&&meter.files>=0);assert.ok(Date.parse(meter.startedAt)>=Date.parse(record.value.epoch.startedAt)&&Date.parse(meter.completedAt)>=Date.parse(meter.startedAt)&&Date.parse(meter.completedAt)<=Date.parse(record.value.closedAt));assert.ok(Date.parse(record.value.closedAt)>Date.parse(record.value.epoch.startedAt));return {...record,results:evidence};}
