export async function measureRetirementInspectionCas(context,closure,objects,{signal}={}){
 assert.equal(context.writeAuthority,false);assert.deepEqual(objects.map(x=>actionIdentity(x.action)),[...closure.sourceActions,...closure.artifactActions].map(actionIdentity));for(const row of objects)assert.equal(row.root,row.action.source);const intent={value:{binding:closure.binding,adoption:{stateSha256:context.adopted.stateSha256}}},observations={};
 const observe=async(name,read)=>{try{const value=await read();observations[name]={ok:true,value};return value;}catch(error){observations[name]={ok:false,error:String(error?.message??error).slice(0,800)};return null;}};
 const measurement=await retirementCasCombination({signal,before:[{name:'adoption-original-before',run:()=>observe('adoptionBefore',()=>adoptedCas(context,intent))}],closureCheck:()=>assertRetirementClosureUnchanged(context,closure),objects,after:[{name:'ordinary-task-boot-ref-native',run:async()=>{const identity=await observe('identity',()=>currentPreparationIdentity());await observe('ordinary',()=>assertOrdinaryIdentity(identity,context.adopted.state.preparationTask.sid));await observe('task',()=>assertRetirementTaskIdle(context));await observe('boot',()=>collectFullBootObservation());await observe('native',()=>loadRetirementNativeTools(context.config).then(x=>x.files));await observe('ref',()=>assertRetirementGitFence(context));}},{name:'adoption-original-tail',run:()=>observe('adoptionAfter',()=>adoptedCas(context,intent))}]});
 const exclusions=['writer-locks-not-acquired','no-frozen-retirement-intent','no-post-source-close-retirement-proof'];if(!observations.ordinary?.ok)exclusions.push('ordinary-writer-not-proved');for(const [name,row]of Object.entries(observations))if(!row.ok)exclusions.push(name+'-rejected');return {version:retirementOperatorVersion,status:'diagnostic-partial',admissionPassed:false,recoveryEligible:false,publicationPerformed:false,measurement,observations,exclusions};
}
/** Only private tests may replace native observation transports. */
export async function executeRetirementForTest({context,adapter,...options}){assert.equal(context.privateTestTopology,true);assert.ok(isRetirementChild(os.tmpdir(),context.config.stateDirectory)&&/^s05d-retirement-test-/.test(path.basename(path.dirname(context.config.stateDirectory))));for(const root of [context.configFile,context.config.repository,context.config.releaseDirectory])assert.ok(isRetirementChild(path.dirname(context.config.stateDirectory),root));return operation(context,options,adapter);}
function privateMoveTopology({root,context,intent,actions}){root=path.resolve(root);assert.equal(context.privateTestTopology,true);assert.ok(isRetirementChild(os.tmpdir(),root)&&/^s05d-retirement-test-/.test(path.basename(root)));for(const file of [context.config.stateDirectory,context.config.repository,context.config.releaseDirectory,context.configFile,context.native?.api?.workerDevVarsSource,context.native?.api?.workerSourceRoot,context.native?.api?.workerLegacySourceRoot,intent.directory,...actions.flatMap(a=>[a.source,a.destination])].filter(Boolean))assert.ok(isRetirementChild(root,file),'Private preimage test escaped its topology');return root;}
export async function retirementCasCombinationForTest({root,...options}){assert.ok(isRetirementChild(os.tmpdir(),root)&&/^s05d-retirement-test-/.test(path.basename(root)));for(const row of options.objects)assert.ok(isRetirementChild(root,row.root));return retirementCasCombination(options);}
export async function preflightRetirementMovesForTest(options){privateMoveTopology(options);return preflightMoves(options.context,options.intent,options.actions,options.adapter);}
export async function preserveRetirementMovesForTest(options){privateMoveTopology(options);const {context,intent,actions,adapter}=options,preimages=await preflightMoves(context,intent,actions,adapter),records=[];for(const action of actions)records.push(await snapshotMove(context,intent,action,adapter,preimages.get(action.objectId)));return records;}
export async function retirementArchiveInventoryForTest(options){privateMoveTopology({...options,actions:options.records.map(x=>x.action)});assert.ok(isRetirementChild(options.root,options.intent.initial.archiveRoot));return archiveInventory(options.context,options.intent,{results:options.records},[],options.adapter,options.profile);}
